/bin/bash -c "node --input-type=module -e \"import { spawnSync } from 'node:child_process';
function rand16() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let out = '';
  for (let i = 0; i < 16; i += 1) {
    out += chars[Math.floor(Math.random() * chars.length)];
  }
  return out;
}
for (let i = 0; i < 25; i += 1) {
  const args = ['--key', rand16(), '--iv', rand16(), '--data1', rand16(), '--data2', rand16()];
  const py = spawnSync('/workspace/dataset/test7_executable', args, { encoding: 'utf8' });
  const js = spawnSync('node', ['/output/test7.mjs', ...args], { encoding: 'utf8' });
  if (py.status "'!== js.status || py.stdout !== js.stdout || py.stderr !== js.stderr) {
    console.log('"'mismatch');
    console.log(JSON.stringify({ args, pyStatus: py.status, jsStatus: js.status, pyStdout: py.stdout, jsStdout: js.stdout, pyStderr: py.stderr, jsStderr: js.stderr }, null, 2));
    process.exit(1);
  }
}
console.log('ok');\""

